"""Neighbour content, part B: Sych, Zina, Lilya, Mikhalych, Tanya -> people/<id>.tsv.

Each character is a dict of three lists: lines, reqs, notes (one tuple per row).
  line: (when, ru, en)
  req:  (gap, months, when, hearts, needs, reward, ru, en, reply_ru, reply_en, sets)
  note: (gap, months, when, hearts, needs_flags, reward, ru, en, sets)
`n` is numbered automatically in list order.
"""
from common import write

COLS = "t n gap months when hearts needs reward text_ru text_en reply_ru reply_en sets".split()


def rows_of(ch):
    out = []
    for when, ru, en in ch["lines"]:
        out.append(["line", "", "", "", when, "", "", "", ru, en, "", "", ""])
    for i, (gap, months, when, hearts, needs, reward, ru, en, rru, ren, sets) in enumerate(ch["reqs"], 1):
        out.append(["req", i, gap, months, when, hearts, needs, reward, ru, en, rru, ren, sets])
    for i, (gap, months, when, hearts, needs, reward, ru, en, sets) in enumerate(ch["notes"], 1):
        out.append(["note", i, gap, months, when, hearts, needs, reward, ru, en, "", "", sets])
    return out


def main():
    for pid, ch in (("sych", SYCH), ("zina", ZINA), ("lilya", LILYA), ("mikhalych", MIKHALYCH), ("tanya", TANYA)):
        write(f"people/{pid}.tsv", COLS, rows_of(ch))


